import { useEffect,useState } from 'react';
import { externalApi } from '../../lib/api.js';
export default function NearbyPerformance(){
  const [months,setMonths]=useState(6),[report,setReport]=useState(null),[error,setError]=useState(''),[retry,setRetry]=useState(0);
  useEffect(()=>{let active=true;setReport(null);setError('');externalApi.call(`/vendor/nearby/performance?months=${months}`).then(r=>{if(active)setReport(r.report);}).catch(e=>{if(active)setError(e.message);});return()=>{active=false;};},[months,retry]);
  const download=()=>{if(!report)return;const rows=[['Metric','Value'],...Object.entries(report.metrics),...Object.entries(report).filter(([key,value])=>!['scope','period','metrics'].includes(key)&&typeof value!=='object')];const blob=new Blob([rows.map(r=>r.map(v=>`"${String(v??'Unavailable').replaceAll('"','""')}"`).join(',')).join('\r\n')],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`starvnt-nearby-${months}-months.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  return <section className="rounded-2xl border border-primary/15 bg-white p-5 space-y-4"><div className="flex flex-wrap justify-between gap-3 items-center"><div><p className="text-[10px] font-bold tracking-widest text-primary">YOUR LOCAL OPPORTUNITY NETWORK</p><h2 className="text-lg font-extrabold">Nearby discovery performance</h2></div><label className="text-xs">Report period<select className="block min-h-11 rounded-xl border px-3" value={months} onChange={e=>setMonths(Number(e.target.value))}><option value={1}>Past month</option><option value={6}>Past six months</option></select></label></div><p className="text-xs text-muted">Nearby discovery only. Impressions, eligibility, notifications, enquiries and payment-verified bookings are separate measurements.</p>{error&&<p role="alert">{error}<button className="min-h-11 underline ml-3" onClick={()=>setRetry(n=>n+1)}>Retry</button></p>}{!report&&!error&&<p role="status">Loading recorded performance…</p>}{report&&<><div className="grid grid-cols-2 lg:grid-cols-4 gap-3">{[['List impressions',report.metrics.LIST_IMPRESSION||0],['Map impressions',report.metrics.MAP_IMPRESSION||0],['Profile views',report.metrics.PROFILE_VIEW||0],['Matching eligibility',report.eligibilityCount],['Matching requests',report.matchingRequests],['Delivered in-app notifications',report.notificationsDelivered],['Genuine enquiries',report.enquiries],['Vendor responses',report.responses],['Quotations submitted',report.quotations],['Confirmed bookings',report.confirmedBookings],['Attributed booking value',`₹${report.attributedBookingValue.toLocaleString('en-IN')}`],['Response rate',report.responseRate==null?'No response history':`${report.responseRate}%`],['Average response time',report.averageResponseTimeMs==null?'Not recorded':`${Math.round(report.averageResponseTimeMs/60000)} min`]].map(([label,value])=><div className="border rounded-xl p-3 min-w-0" key={label}><span className="text-[10px] text-muted">{label}</span><strong className="block text-lg mt-2 break-words">{value}</strong></div>)}</div><p className="text-[10px] text-muted">{new Date(report.period.from).toLocaleDateString()} – {new Date(report.period.to).toLocaleDateString()} · server records · External bookings excluded.</p><button className="min-h-11 border rounded-xl px-4 text-sm" onClick={download}>Download recorded report</button></>}</section>;
}
